+/// Euclidean algorithm, returning `seed * a^-1 mod n`. The result is
+/// canonical when `seed` is.
+#[inline]
+fn invert_canonical(a: [u64; 4], seed: [u64; 4]) -> [u64; 4] {
+    const ONE: [u64; 4] = [1, 0, 0, 0];
